func TestTeam(t *testing.T) {
	e := apitest.New(t)
	var inv store.Invite
	e.MustDo(http.StatusCreated, "POST", "/v1/invites", e.Acme.Key, map[string]string{"email": "new@people.example", "role": "member"}, &inv)
	msgs := e.Mail.Messages()
	if len(msgs) != 1 || msgs[0].To != "new@people.example" || !strings.Contains(msgs[0].Subject, "Acme") {
		t.Fatalf("emails = %+v", msgs)
	}
	m := regexp.MustCompile(`token=([^\s]+)`).FindStringSubmatch(msgs[0].Body)
	if m == nil {
		t.Fatalf("no link in %q", msgs[0].Body)
	}
	token, _ := url.QueryUnescape(m[1])
	if r := e.Do("POST", "/v1/invites", e.Acme.Key, map[string]string{"email": "owner@acme.example", "role": "member"}); r.Code != http.StatusConflict {
		t.Fatalf("invite a member: %s", r)
	}
	var accepted struct {
		User   store.User   `json:"user"`
		APIKey store.APIKey `json:"api_key"`
	}
	e.MustDo(http.StatusCreated, "POST", "/v1/invites/accept", "", map[string]string{"token": token, "name": "New Person"}, &accepted)
	if accepted.User.Email != "new@people.example" || accepted.APIKey.Token == "" {
		t.Fatalf("accepted = %+v", accepted)
	}
	if r := e.Do("POST", "/v1/invites/accept", "", map[string]string{"token": "invite_nope", "name": "X"}); r.Code != http.StatusNotFound {
		t.Fatalf("unknown token: %s", r)
	}
	newKey := accepted.APIKey.Token
	var me struct{ Role string }
	e.MustDo(http.StatusOK, "GET", "/v1/me", newKey, nil, &me)
	if me.Role != "member" {
		t.Fatalf("role = %s", me.Role)
	}
	if r := e.Do("POST", "/v1/invites", newKey, map[string]string{"email": "x@people.example", "role": "member"}); r.Code != http.StatusForbidden {
		t.Fatalf("a member invites: %s", r)
	}
	var members struct {
		Items []struct {
			UserID string `json:"user_id"`
			Role   string `json:"role"`
		}
	}
	e.MustDo(http.StatusOK, "GET", "/v1/members", e.Acme.Key, nil, &members)
	if len(members.Items) != 2 {
		t.Fatalf("members = %+v", members)
	}
	e.MustDo(http.StatusOK, "PATCH", "/v1/members/"+accepted.User.ID, e.Acme.Key, map[string]string{"role": "billing"}, nil)
	e.MustDo(http.StatusOK, "GET", "/v1/me", newKey, nil, &me)
	if me.Role != "billing" {
		t.Fatalf("role after the change = %s", me.Role)
	}
	e.MustDo(http.StatusNoContent, "DELETE", "/v1/members/"+accepted.User.ID, e.Acme.Key, nil, nil)
	if r := e.Do("GET", "/v1/me", newKey, nil); r.Code != http.StatusUnauthorized {
		t.Fatalf("a removed member's key: %s", r)
	}

	var second store.Invite
	e.MustDo(http.StatusCreated, "POST", "/v1/invites", e.Acme.Key, map[string]string{"email": "later@people.example", "role": "viewer"}, &second)
	e.MustDo(http.StatusNoContent, "DELETE", "/v1/invites/"+second.ID, e.Acme.Key, nil, nil)
	var pending struct{ Items []store.Invite }
	e.MustDo(http.StatusOK, "GET", "/v1/invites", e.Acme.Key, nil, &pending)
	if len(pending.Items) != 0 {
		t.Fatalf("pending invites = %+v", pending.Items)
	}
}

func TestAPIKeys(t *testing.T) {
	e := apitest.New(t)
	var k store.APIKey
	e.MustDo(http.StatusCreated, "POST", "/v1/api-keys", e.Acme.Key, map[string]string{"name": "CI"}, &k)
	if !strings.HasPrefix(k.Token, "tly_") || k.Name != "CI" {
		t.Fatalf("key = %+v", k)
	}
	e.MustDo(http.StatusOK, "GET", "/v1/org", k.Token, nil, nil)
	var keys struct{ Items []store.APIKey }
	e.MustDo(http.StatusOK, "GET", "/v1/api-keys", e.Acme.Key, nil, &keys)
	if len(keys.Items) != 2 {
		t.Fatalf("keys = %+v", keys)
	}
	if r := e.Do("DELETE", "/v1/api-keys/"+k.ID, e.Globex.Key, nil); r.Code != http.StatusNotFound {
		t.Fatalf("revoke another org's key: %s", r)
	}
	e.MustDo(http.StatusNoContent, "DELETE", "/v1/api-keys/"+k.ID, e.Acme.Key, nil, nil)
	if r := e.Do("GET", "/v1/org", k.Token, nil); r.Code != http.StatusUnauthorized {
		t.Fatalf("revoked key: %s", r)
	}
}

func TestOrgSettings(t *testing.T) {
	e := apitest.New(t)
	var o store.Org
	e.MustDo(http.StatusOK, "PATCH", "/v1/org", e.Acme.Key, map[string]any{"tax_rate_bp": 2000, "time_zone": "Asia/Tokyo"}, &o)
	if o.TaxRateBP != 2000 || o.TimeZone != "Asia/Tokyo" {
		t.Fatalf("org = %+v", o)
	}
	if r := e.Do("PATCH", "/v1/org", e.Acme.Key, map[string]any{"time_zone": "Not/AZone"}); r.Code != http.StatusUnprocessableEntity {
		t.Fatalf("bad time zone: %s", r)
	}
	_, member := e.AddMember(e.Acme, "m@acme.example", store.RoleMember)
	if r := e.Do("PATCH", "/v1/org", member, map[string]any{"name": "Hacked"}); r.Code != http.StatusForbidden {
		t.Fatalf("a member changes the org: %s", r)
	}
}
// Package apitest builds a whole Tally service for tests: the store, a fake clock, the fake payment gateway, an email
// outbox, fake webhook receivers and DNS, the services and the API server, with two organizations to start from.
package apitest

import (
	"bytes"
	"context"
	"encoding/json"
	"fmt"
	"io"
	"net"
	"net/http"
	"net/http/httptest"
	"strings"
	"sync"
	"testing"
	"time"

	"example.com/tally/internal/api"
	"example.com/tally/internal/clock"
	"example.com/tally/internal/mail"
	"example.com/tally/internal/payments"
	"example.com/tally/internal/store"
	"example.com/tally/internal/subscriptions"
	"example.com/tally/internal/webhooks"
)

// Start is the fake clock's time when an Env is created.
var Start = time.Date(2026, time.January, 15, 10, 0, 0, 0, time.UTC)

// Env is a running service and the fakes around it.
type Env struct {
	T        testing.TB
	Store    *store.Store
	Clock    *clock.Fake
	Gateway  *payments.Fake
	Mail     *mail.Outbox
	HTTP     *FakeHTTP // the organizations' webhook receivers
	DNS      *FakeDNS
	Webhooks *webhooks.Service
	Payments *payments.Service
	Subs     *subscriptions.Service
	Server   *api.Server

	// Acme (team plan, America/New_York) and Globex (business plan, Europe/Berlin) each have an owner with an API key.
	Acme, Globex Org
}

// Org is an organization with its owner and the owner's API key.
type Org struct {
	store.Org
	Owner store.User
	Key   string
}

// New builds a service for a test.
func New(t testing.TB) *Env {
	t.Helper()
	e := &Env{T: t, Store: store.New(), Clock: clock.NewFake(Start), Gateway: &payments.Fake{}, Mail: &mail.Outbox{}, HTTP: &FakeHTTP{}, DNS: &FakeDNS{}}
	e.DNS.Set("hooks.acme.example", "93.184.216.34")
	e.DNS.Set("hooks.globex.example", "93.184.216.35")
	e.Webhooks = webhooks.New(webhooks.Options{Store: e.Store, Clock: e.Clock, Doer: e.HTTP, Resolver: e.DNS})
	e.Payments = &payments.Service{Store: e.Store, Gateway: e.Gateway, Clock: e.Clock, Publisher: e.Webhooks}
	e.Subs = &subscriptions.Service{Store: e.Store, Payments: e.Payments, Clock: e.Clock, Publisher: e.Webhooks}
	e.Server = api.New(e.Store, api.Options{Clock: e.Clock, Payments: e.Payments, Subscriptions: e.Subs, Webhooks: e.Webhooks, Mail: e.Mail})
	e.Acme = e.NewOrg("Acme", store.OrgTeam, "America/New_York")
	e.Globex = e.NewOrg("Globex", store.OrgBusiness, "Europe/Berlin")
	return e
}

// NewOrg adds an organization with an owner (owner@<name>.example) and the owner's API key.
func (e *Env) NewOrg(name string, plan store.OrgPlan, timeZone string) Org {
	e.T.Helper()
	now := e.Clock.Now()
	o, err := e.Store.CreateOrg(name, plan, timeZone, 0, now)
	if err != nil {
		e.T.Fatalf("create org %s: %v", name, err)
	}
	u, err := e.Store.CreateUser("owner@"+strings.ToLower(name)+".example", name+" Owner", now)
	if err != nil {
		e.T.Fatalf("create owner of %s: %v", name, err)
	}
	if _, err := e.Store.AddMember(o.ID, u.ID, store.RoleOwner, now); err != nil {
		e.T.Fatal(err)
	}
	k, err := e.Store.CreateAPIKey(o.ID, u.ID, "Owner key", now)
	if err != nil {
		e.T.Fatal(err)
	}
	return Org{Org: o, Owner: u, Key: k.Token}
}

// AddMember adds a new user with this email address to org with a role, and returns them with an API key of theirs.
func (e *Env) AddMember(org Org, email string, role store.Role) (store.User, string) {
	e.T.Helper()
	now := e.Clock.Now()
	u, ok := e.Store.UserByEmail(email)
	if !ok {
		var err error
		if u, err = e.Store.CreateUser(email, strings.Split(email, "@")[0], now); err != nil {
			e.T.Fatal(err)
		}
	}
	if _, err := e.Store.AddMember(org.ID, u.ID, role, now); err != nil {
		e.T.Fatal(err)
	}
	k, err := e.Store.CreateAPIKey(org.ID, u.ID, "Key of "+email, now)
	if err != nil {
		e.T.Fatal(err)
	}
	return u, k.Token
}

// Response is the server's answer.
type Response struct {
	Code   int
	Header http.Header
	Body   []byte
}

