// Permission is something an endpoint needs a member's role to allow.
type Permission int

// Permissions. Anyone is every role, viewers included.
const (
	Anyone Permission = iota
	WriteCustomers
	WriteSubscriptions
	WritePlans
	WriteInvoices
	ReadRevenue
	ManageWebhooks
	ManageOrg
)

// Can reports whether a role has a permission.
func Can(r store.Role, p Permission) bool {
	switch p {
	case Anyone:
		return r.Valid()
	case WriteCustomers, WriteSubscriptions:
		return r != store.RoleViewer
	case WritePlans, WriteInvoices, ReadRevenue:
		return r == store.RoleOwner || r == store.RoleAdmin || r == store.RoleBilling
	case ManageWebhooks, ManageOrg:
		return CanManageTeam(r)
	}
	return false
}

