// last_owner, anyone else gets forbidden.
func (s *Server) updateMember(w http.ResponseWriter, r *http.Request, p auth.Principal) {
	var in struct {
		Role store.Role `json:"role"`
	}
	if !decode(w, r, &in) {
		return
	}
	target := r.PathValue("user_id")
	if target == p.UserID {
		if in.Role != store.RoleOwner && s.store.IsLastOwner(p.OrgID, target) {
			s.storeError(w, store.ErrLastOwner)
			return
		}
		forbidden(w)
		return
	}
	cur, ok := s.store.Member(p.OrgID, target)
	if !ok {
		s.storeError(w, store.ErrNotFound)
		return
	}
	if !auth.CanAssign(p.Role, cur.Role) || !auth.CanAssign(p.Role, in.Role) {
		forbidden(w)
		return
	}
	m, err := s.store.SetMemberRole(p.OrgID, target, in.Role)
	if err != nil {
		s.storeError(w, err)
		return
	}
	writeJSON(w, http.StatusOK, s.memberView(m))
}

