package api_test

import (
	"net/http"
	"testing"

	"example.com/tally/internal/apitest"
	"example.com/tally/internal/store"
)

var allRoles = []store.Role{store.RoleOwner, store.RoleAdmin, store.RoleBilling, store.RoleMember, store.RoleViewer}

// The role sets of the role table.
var (
	everyone        = allRoles
	notViewer       = []store.Role{store.RoleOwner, store.RoleAdmin, store.RoleBilling, store.RoleMember}
	finance         = []store.Role{store.RoleOwner, store.RoleAdmin, store.RoleBilling}
	ownersAndAdmins = []store.Role{store.RoleOwner, store.RoleAdmin}
)

// roleRule is one endpoint of the role table and the roles it allows. The IDs in the paths do not exist: an allowed request
// answers 404 or 422 rather than 403.
var roleRules = []struct {
	method, path string
	body         any
	allowed      []store.Role
}{
	{"GET", "/v1/customers", nil, everyone},
	{"GET", "/v1/customers/export.csv", nil, everyone},
	{"GET", "/v1/customers/cus_nope", nil, everyone},
	{"POST", "/v1/customers", map[string]string{"name": "Jane", "email": "jane@example.com"}, notViewer},
	{"PATCH", "/v1/customers/cus_nope", map[string]string{"name": "Jane"}, notViewer},
	{"DELETE", "/v1/customers/cus_nope", nil, notViewer},

	{"GET", "/v1/plans", nil, everyone},
	{"GET", "/v1/plans/plan_nope", nil, everyone},
	{"POST", "/v1/plans", map[string]any{}, finance},
	{"PATCH", "/v1/plans/plan_nope", map[string]any{}, finance},

	{"GET", "/v1/subscriptions", nil, everyone},
	{"GET", "/v1/subscriptions/sub_nope", nil, everyone},
	{"POST", "/v1/subscriptions", map[string]any{}, notViewer},
	{"PATCH", "/v1/subscriptions/sub_nope", map[string]any{}, notViewer},
	{"POST", "/v1/subscriptions/sub_nope/cancel", nil, notViewer},
	{"POST", "/v1/subscriptions/sub_nope/usage", map[string]any{"quantity": 1}, notViewer},

	{"GET", "/v1/invoices", nil, everyone},
	{"GET", "/v1/invoices/inv_nope", nil, everyone},
	{"GET", "/v1/invoices/inv_nope/lines", nil, everyone},
	{"POST", "/v1/invoices", map[string]any{}, finance},
	{"POST", "/v1/invoices/inv_nope/pay", nil, finance},
	{"POST", "/v1/invoices/inv_nope/void", nil, finance},
	{"GET", "/v1/payments", nil, everyone},
	{"GET", "/v1/reports/revenue", nil, finance},

	{"GET", "/v1/webhook-endpoints", nil, ownersAndAdmins},
	{"POST", "/v1/webhook-endpoints", map[string]any{}, ownersAndAdmins},
	{"GET", "/v1/webhook-endpoints/whe_nope", nil, ownersAndAdmins},
	{"PATCH", "/v1/webhook-endpoints/whe_nope", map[string]any{}, ownersAndAdmins},
	{"DELETE", "/v1/webhook-endpoints/whe_nope", nil, ownersAndAdmins},
	{"GET", "/v1/webhook-endpoints/whe_nope/deliveries", nil, ownersAndAdmins},
	{"GET", "/v1/events", nil, ownersAndAdmins},
	{"GET", "/v1/events/evt_nope", nil, ownersAndAdmins},

	{"GET", "/v1/org", nil, everyone},
	{"PATCH", "/v1/org", map[string]any{"name": "Acme Inc"}, ownersAndAdmins},
	{"GET", "/v1/members", nil, everyone},
	{"GET", "/v1/invites", nil, everyone},
	{"POST", "/v1/invites", map[string]string{"email": "new@people.example", "role": "member"}, ownersAndAdmins},
	{"DELETE", "/v1/invites/inv_nope", nil, ownersAndAdmins},
}

// TestRoleTable sends every endpoint of the role table as every role. A role outside the table gets exactly 403
// {"error":"forbidden"}; a role inside it is not refused.
func TestRoleTable(t *testing.T) {
	for _, rule := range roleRules {
		for _, role := range allRoles {
			t.Run(rule.method+" "+rule.path+" as "+string(role), func(t *testing.T) {
				e := apitest.New(t)
				key := keyWithRole(e, role)
				r := e.Do(rule.method, rule.path, key, rule.body)
				if containsRole(rule.allowed, role) {
					if r.Code == http.StatusUnauthorized || r.Code == http.StatusForbidden || r.Code >= 500 {
						t.Fatalf("allowed, but got %s", r)
					}
					return
				}
				expectForbidden(t, r)
			})
		}
	}
}

// TestRefusedRequestChangesNothing checks that a refused write leaves the data as it was.
func TestRefusedRequestChangesNothing(t *testing.T) {
	e := apitest.New(t)
	_, viewer := e.AddMember(e.Acme, "viewer@acme.example", store.RoleViewer)
	_, member := e.AddMember(e.Acme, "member@acme.example", store.RoleMember)
	expectForbidden(t, e.Do("POST", "/v1/customers", viewer, map[string]string{"name": "Jane", "email": "jane@example.com"}))
	expectForbidden(t, e.Do("PATCH", "/v1/org", member, map[string]any{"name": "Hacked"}))
	var customers struct{ Items []store.Customer }
	e.MustDo(http.StatusOK, "GET", "/v1/customers", e.Acme.Key, nil, &customers)
	if len(customers.Items) != 0 {
		t.Fatalf("customers = %+v", customers.Items)
	}
	var org store.Org
	e.MustDo(http.StatusOK, "GET", "/v1/org", e.Acme.Key, nil, &org)
	if org.Name != "Acme" {
		t.Fatalf("org name = %q", org.Name)
	}
}

// TestRoleChangeAppliesToExistingKeys checks that a role change reaches the member's existing key at once.
func TestRoleChangeAppliesToExistingKeys(t *testing.T) {
	e := apitest.New(t)
	u, key := e.AddMember(e.Acme, "viewer@acme.example", store.RoleViewer)
	customer := map[string]string{"name": "Jane", "email": "jane@example.com"}
	expectForbidden(t, e.Do("POST", "/v1/customers", key, customer))
	e.MustDo(http.StatusOK, "PATCH", "/v1/members/"+u.ID, e.Acme.Key, map[string]string{"role": "member"}, nil)
	e.MustDo(http.StatusCreated, "POST", "/v1/customers", key, customer, nil)
	e.MustDo(http.StatusOK, "PATCH", "/v1/members/"+u.ID, e.Acme.Key, map[string]string{"role": "viewer"}, nil)
	expectForbidden(t, e.Do("POST", "/v1/customers", key, map[string]string{"name": "John", "email": "john@example.com"}))
}

// TestOnlyOwnersGrantOwnerAndAdmin checks who may give, change and remove the owner and admin roles.
func TestOnlyOwnersGrantOwnerAndAdmin(t *testing.T) {
	e := apitest.New(t)
	adminU, admin := e.AddMember(e.Acme, "admin@acme.example", store.RoleAdmin)
	otherAdminU, _ := e.AddMember(e.Acme, "other-admin@acme.example", store.RoleAdmin)
	memberU, _ := e.AddMember(e.Acme, "member@acme.example", store.RoleMember)
	ownerID := e.Acme.Owner.ID

	// An admin manages members, but not owners or admins, and cannot give those roles.
	expectForbidden(t, e.Do("PATCH", "/v1/members/"+memberU.ID, admin, map[string]string{"role": "admin"}))
	expectForbidden(t, e.Do("PATCH", "/v1/members/"+memberU.ID, admin, map[string]string{"role": "owner"}))
	expectForbidden(t, e.Do("PATCH", "/v1/members/"+ownerID, admin, map[string]string{"role": "billing"}))
	expectForbidden(t, e.Do("PATCH", "/v1/members/"+otherAdminU.ID, admin, map[string]string{"role": "member"}))
	expectForbidden(t, e.Do("DELETE", "/v1/members/"+ownerID, admin, nil))
	expectForbidden(t, e.Do("DELETE", "/v1/members/"+otherAdminU.ID, admin, nil))
	expectForbidden(t, e.Do("POST", "/v1/invites", admin, map[string]string{"email": "x@people.example", "role": "admin"}))
	expectForbidden(t, e.Do("POST", "/v1/invites", admin, map[string]string{"email": "y@people.example", "role": "owner"}))
	e.MustDo(http.StatusOK, "PATCH", "/v1/members/"+memberU.ID, admin, map[string]string{"role": "billing"}, nil)
	e.MustDo(http.StatusCreated, "POST", "/v1/invites", admin, map[string]string{"email": "z@people.example", "role": "member"}, nil)
	e.MustDo(http.StatusNoContent, "DELETE", "/v1/members/"+memberU.ID, admin, nil, nil)

	// An owner may change the admins.
	e.MustDo(http.StatusOK, "PATCH", "/v1/members/"+otherAdminU.ID, e.Acme.Key, map[string]string{"role": "member"}, nil)
	e.MustDo(http.StatusOK, "PATCH", "/v1/members/"+adminU.ID, e.Acme.Key, map[string]string{"role": "owner"}, nil)
}

// TestNobodyChangesOwnRole checks self-changes: 403 for anyone, and last_owner for a sole owner who demotes themselves.
func TestNobodyChangesOwnRole(t *testing.T) {
	e := apitest.New(t)
	_, admin := e.AddMember(e.Acme, "admin@acme.example", store.RoleAdmin)
	ownerID := e.Acme.Owner.ID
	expectLastOwner(t, e.Do("PATCH", "/v1/members/"+ownerID, e.Acme.Key, map[string]string{"role": "billing"}))
	expectForbidden(t, e.Do("PATCH", "/v1/members/"+ownerID, e.Acme.Key, map[string]string{"role": "owner"}))
	expectForbidden(t, e.Do("PATCH", "/v1/members/"+e.Store.Members(e.Acme.ID)[1].UserID, admin, map[string]string{"role": "member"}))

	owner2U, owner2 := e.AddMember(e.Acme, "owner2@acme.example", store.RoleOwner)
	expectForbidden(t, e.Do("PATCH", "/v1/members/"+ownerID, e.Acme.Key, map[string]string{"role": "admin"}))
	e.MustDo(http.StatusOK, "PATCH", "/v1/members/"+ownerID, owner2, map[string]string{"role": "admin"}, nil)
	expectLastOwner(t, e.Do("PATCH", "/v1/members/"+owner2U.ID, owner2, map[string]string{"role": "admin"}))
	expectLastOwner(t, e.Do("DELETE", "/v1/members/"+owner2U.ID, owner2, nil))
}

// TestAnyoneMayLeave checks that every role may remove itself, and that the last owner may not.
func TestAnyoneMayLeave(t *testing.T) {
	e := apitest.New(t)
	for _, role := range []store.Role{store.RoleBilling, store.RoleMember, store.RoleViewer} {
		u, key := e.AddMember(e.Acme, string(role)+"@acme.example", role)
		e.MustDo(http.StatusNoContent, "DELETE", "/v1/members/"+u.ID, key, nil, nil)
		if r := e.Do("GET", "/v1/org", key, nil); r.Code != http.StatusUnauthorized {
			t.Fatalf("%s's key after leaving: %s", role, r)
		}
	}
	expectLastOwner(t, e.Do("DELETE", "/v1/members/"+e.Acme.Owner.ID, e.Acme.Key, nil))
}

// TestRemovingMembers checks who may remove other members.
func TestRemovingMembers(t *testing.T) {
	e := apitest.New(t)
	_, billing := e.AddMember(e.Acme, "billing@acme.example", store.RoleBilling)
	_, member := e.AddMember(e.Acme, "member@acme.example", store.RoleMember)
	adminU, _ := e.AddMember(e.Acme, "admin@acme.example", store.RoleAdmin)
	memberU := e.Store.Members(e.Acme.ID)[2]
	expectForbidden(t, e.Do("DELETE", "/v1/members/"+memberU.UserID, billing, nil))
	expectForbidden(t, e.Do("DELETE", "/v1/members/"+memberU.UserID, member, nil))
	e.MustDo(http.StatusNoContent, "DELETE", "/v1/members/"+memberU.UserID, e.Acme.Key, nil, nil)
	e.MustDo(http.StatusNoContent, "DELETE", "/v1/members/"+adminU.ID, e.Acme.Key, nil, nil)
	if r := e.Do("DELETE", "/v1/members/"+memberU.UserID, e.Acme.Key, nil); r.Code != http.StatusNotFound {
		t.Fatalf("a removed member again: %s", r)
	}
}

// TestAPIKeyRules checks who may create, list and revoke API keys.
func TestAPIKeyRules(t *testing.T) {
	e := apitest.New(t)
	memberU, member := e.AddMember(e.Acme, "member@acme.example", store.RoleMember)
	_, viewer := e.AddMember(e.Acme, "viewer@acme.example", store.RoleViewer)
	memberKey := mustKey(e, memberU.ID, member)
	ownerKey, _ := e.Store.APIKeyByToken(e.Acme.Key)

	var own store.APIKey
	e.MustDo(http.StatusCreated, "POST", "/v1/api-keys", viewer, map[string]string{"name": "Mine"}, &own)
	e.MustDo(http.StatusNoContent, "DELETE", "/v1/api-keys/"+own.ID, viewer, nil, nil)

	expectForbidden(t, e.Do("DELETE", "/v1/api-keys/"+ownerKey.ID, viewer, nil))
	expectForbidden(t, e.Do("DELETE", "/v1/api-keys/"+ownerKey.ID, member, nil))
	expectForbidden(t, e.Do("DELETE", "/v1/api-keys/"+memberKey.ID, viewer, nil))

	var mine struct{ Items []store.APIKey }
	e.MustDo(http.StatusOK, "GET", "/v1/api-keys", member, nil, &mine)
	if len(mine.Items) != 1 || mine.Items[0].ID != memberKey.ID {
		t.Fatalf("a member's keys = %+v", mine.Items)
	}
	var all struct{ Items []store.APIKey }
	e.MustDo(http.StatusOK, "GET", "/v1/api-keys", e.Acme.Key, nil, &all)
	if len(all.Items) != 3 {
		t.Fatalf("an owner's keys = %+v", all.Items)
	}

	e.MustDo(http.StatusNoContent, "DELETE", "/v1/api-keys/"+memberKey.ID, e.Acme.Key, nil, nil)
	if r := e.Do("GET", "/v1/org", member, nil); r.Code != http.StatusUnauthorized {
		t.Fatalf("a revoked key: %s", r)
	}
}

// keyWithRole returns an API key of a member of Acme with the role. Owners use Acme's owner.
func keyWithRole(e *apitest.Env, role store.Role) string {
	if role == store.RoleOwner {
		return e.Acme.Key
	}
	_, key := e.AddMember(e.Acme, string(role)+"@acme.example", role)
	return key
}

// mustKey returns the stored key that has the token.
func mustKey(e *apitest.Env, userID, token string) store.APIKey {
	k, ok := e.Store.APIKeyByToken(token)
	if !ok || k.UserID != userID {
		e.T.Fatalf("no key for %s", userID)
	}
	return k
}

func containsRole(roles []store.Role, role store.Role) bool {
	for _, r := range roles {
		if r == role {
			return true
		}
	}
	return false
}

// expectForbidden checks the refusal exactly: 403 {"error":"forbidden"}.
func expectForbidden(t *testing.T, r *apitest.Response) {
	t.Helper()
	expectError(t, r, http.StatusForbidden, "forbidden")
}

// expectLastOwner checks the refusal exactly: 409 {"error":"last_owner"}.
func expectLastOwner(t *testing.T, r *apitest.Response) {
	t.Helper()
	expectError(t, r, http.StatusConflict, "last_owner")
}

func expectError(t *testing.T, r *apitest.Response, status int, code string) {
	t.Helper()
	if r.Code != status {
		t.Fatalf("want %d %s, got %s", status, code, r)
	}
	if got := r.Map(t); len(got) != 1 || got["error"] != code {
		t.Fatalf("want the body {\"error\":%q}, got %s", code, r)
	}
}

